class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        # Sort queries based on right endpoint
        queries.sort(key=lambda x: x[1])

        # Initialize variables
        total_decremented = 0
        current_sum = sum(nums)

        for l, r, val in queries:
            # Calculate the number of decrements needed to make the subarray [l, r] zero
            decrement_needed = (r - l + 1) * val

            # Check if we can perform this operation without exceeding the total decremented amount
            if current_sum - total_decremented >= decrement_needed:
                total_decremented += decrement_needed
                current_sum -= decrement_needed
            else:
                return -1

        return len(queries)

