class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        res = 0

        for l, r, v in queries:
            if nums[l] >= v:
                continue

            needed = v - nums[l]
            res += ceil(needed / (r - l + 1))

        return res if res else -1

class Solution:
