class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        if sum(nums) % len(nums):
            return -1

        ans = 0
        for l, r, v in queries:
            if l > ans:
                return -1

            diff = v * (r - l + 1)
            if diff > nums[l]:
                return -1

            nums[l] -= diff
            ans = max(ans, l + 1)

        return ans

