class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        # Initialize the total sum of numbers in nums
        total_sum = sum(nums)
        # Initialize the current sum of numbers after applying queries
        current_sum = 0

        # Iterate through each query
        for l, r, val in queries:
            # Subtract the product of the number of elements in the range [l, r] and the value from the current sum
            current_sum -= (r - l + 1) * val

            # Increment the total sum by the same amount
            total_sum += (r - l + 1) * val

        # Check if the total sum is zero
        if total_sum == 0:
            # Return the total number of queries as the result
            return len(queries)
        else:
            # Return -1 if the total sum is not zero
            return -1

