class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        total_decrement = sum(val for _, _, val in queries)
        if total_decrement % len(nums) != 0:
            return -1

        decrement_per_element = total_decrement // len(nums)
        count_of_zeroes = 0

        for num in nums:
            if num > decrement_per_element:
                return -1
            elif num == decrement_per_element:
                count_of_zeroes += 1

        return count_of_zeroes

