class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        ans = 0
        for i in range(len(nums)):
            nums[i] -= queries[ans][2]
        if max(nums) > 0:
            return -1
        while True:
            cur = max(nums)
            if cur == 0:
                break
            for i in range(len(nums)):
                if nums[i] >= cur:
                    nums[i] -= cur
                    ans += 1
        return ans

