class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        # Sort the queries based on the right boundary
        queries.sort(key=lambda x: x[1])

        total_decrement = 0

        for l, r, val in queries:
            # Calculate the number of decrements needed for the current query
            decrement_needed = max(0, r - l + 1 - total_decrement)

            if decrement_needed > val:
                return -1

            # Update the total number of decrements
            total_decrement += val

        # Check if all elements in nums are zero
        return sum(num == 0 for num in nums) == len(nums)

