def count_distinct_xor_values(N: int, A: List[int]) -> int:
    distinct_xor_values = set()

    for i in range(N):
        for j in range(i + 1, N):
            distinct_xor_values.add(A[i] ^ A[j])

    return len(distinct_xor_values)

