def count_xor_values(N, A):
    xor_values = set()
    for i in range(1 << N):
        current_xor = 0
        for j in range(N):
            if i & (1 << j):
                current_xor ^= A[j]
        xor_values.add(current_xor)
    return len(xor_values)

