def calculate_max_same_probability(N, dice_faces):
    max_prob = 0.0
    for i in range(N):
        for j in range(i+1, N):
            common_faces = set(dice_faces[i]) & set(dice_faces[j])
            total_faces = len(dice_faces[i]) * len(dice_faces[j])
            prob = len(common_faces) / total_faces
            if prob > max_prob:
                max_prob = prob
    return round(max_prob, 8)

