def calculate_max_probability(n, dice_info):
    max_prob = 0
    for i in range(n):
        for j in range(i+1, n):
            face_counts = defaultdict(int)
            for k in range(dice_info[i][0]):
                face_counts[dice_info[i][1][k]] += 1
            for k in range(dice_info[j][0]):
                face_counts[dice_info[j][1][k]] += 1
            max_prob = max(max_prob, sum(face_counts.values()) / (dice_info[i][0] + dice_info[j][0]))
    return max_prob

def main():
