def max_dice_match_probability(N, dice_faces):
    # Calculate the total number of possible outcomes for rolling N dice
    total_outcomes = 1
    for k in dice_faces:
        total_outcomes *= k

    # Initialize a dictionary to store the frequency of each number across all dice
    number_frequency = {}

    # Iterate through each pair of dice and count the occurrences of each number
    for i in range(N):
        for j in range(i+1, N):
            for num in dice_faces[i]:
                if num in number_frequency:
                    number_frequency[num] += 1
                else:
                    number_frequency[num] = 1

    # Calculate the probability of matching pairs
    match_probability = 0
    for num, freq in number_frequency.items():
        if freq > 1:
            match_probability += freq * (freq - 1) / (total_outcomes * (total_outcomes - 1))

    return match_probability

