class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        freq_map = Counter(nums)
        max_freq = 0

        for start in range(len(nums)):
            end = start
            current_sum = nums[start]

            while end < len(nums):
                if current_sum + k >= k * (end - start + 1):
                    max_freq = max(max_freq, freq_map[end])
                    current_sum += nums[end]
                    end += 1
                else:
                    break

            if current_sum + k >= k * (len(nums) - start + 1):
                max_freq = max(max_freq, freq_map[len(nums) - start])

        return max_freq

