        if len(original) != len(bounds):
            return 0

        # Create a dictionary to store the range for each element in original
        range_dict = {}
        for i in range(len(original)):
            start, end = bounds[i]
            if start not in range_dict:
                range_dict[start] = []
            range_dict[start].append(end)

        # Initialize variables
        dp = [0] * len(original)
        dp[0] = 1

        # Fill the dp array
        for i in range(1, len(original)):
            prev_value = original[i - 1]
            prev_range = range_dict.get(prev_value, [])

            for j in prev_range:
                if j >= original[i]:
                    dp[i] += dp[j - 1]

        return dp[-1]

